    fn object_field(name: &str, required: bool, type_ref: TypeRef) -> Field {
        Field {
            constraints: None,
            example_source: crate::ir::FieldExampleSource::Property,
            wire_name: name.to_string(),
            py_name: name.to_string(),
            type_ref,
            optional: !required,
            nullable: false,
            spec_required: required,
            docstring: None,
            example: None,
            declared_name: None,
            deprecated: false,
            admits_only_empty_object: false,
            xml: None,
            inherited_from_flattened_parent: false,
            min_length: None,
            max_length: None,
        }
    }

    #[test]
    fn declared_names_become_python_parameters_as_fern_writes_them() {
        assert_eq!(super::python_parameter_name("Archive Host"), "archive_host");
        assert_eq!(super::python_parameter_name("class"), "class_");
        assert_eq!(super::python_parameter_name("2fa"), "_2fa");
        assert_eq!(super::python_parameter_name("lift-pass"), "lift_pass");
    }

    #[test]
    fn operation_servers_make_environment_fields_and_pick_each_requests_field() {
        let doc: OpenApi = serde_json::from_value(serde_json::json!({
            "servers": [{"url": "https://lockers.test/v2"}],
            "paths": {
                "/lockers": {"get": {"responses": {}}},
                "/archive": {"get": {"servers": [
                    {"url": "https://archive.lockers.test/v1", "x-fern-server-name": "Archive Host"}
                ], "responses": {}}},
                "/own": {"get": {"servers": [
                    {"url": "https://lockers.test/v2", "x-crozier-server-name": "main"}
                ], "responses": {}}},
            },
        }))
        .unwrap();
        assert_eq!(
            super::operation_server_urls(&doc),
            [
                (
                    "archive_host".to_string(),
                    "https://archive.lockers.test/v1".to_string()
                ),
                ("main".to_string(), "https://lockers.test/v2".to_string()),
            ]
        );
        let field =
            |route: &str| super::environment_field(&doc, doc.paths[route].get.as_ref().unwrap());
        assert_eq!(field("/lockers"), super::EnvironmentField::Base);
        assert_eq!(
            field("/archive"),
            super::EnvironmentField::Named("archive_host".to_string())
        );
        // A first server that is the document's own reads `base`.
        assert_eq!(field("/own"), super::EnvironmentField::Base);
        assert_eq!(field("/archive").to_string(), "archive_host");
        assert_eq!(super::EnvironmentField::Base.to_string(), "base");
    }

    #[test]
    fn hyphenated_tag_ids_lowercase_the_method_segment() {
        let tag = Some("Gates");
        assert_eq!(
            method_from_hyphenated_tag_id("gates-checkStatus", tag).as_deref(),
            Some("checkstatus")
        );
        assert_eq!(
            method_from_hyphenated_tag_id("Gates-openAll", tag).as_deref(),
            Some("openall")
        );
        assert_eq!(
            method_from_hyphenated_tag_id("gates-all", tag).as_deref(),
            Some("all_")
        );
        assert_eq!(
            method_from_hyphenated_tag_id("gates-list", tag).as_deref(),
            Some("list")
        );
        // Two hyphens, another prefix, no method or no tag are not this form.
        assert_eq!(
            method_from_hyphenated_tag_id("gates-check-status", tag),
            None
        );
        assert_eq!(
            method_from_hyphenated_tag_id("other-checkStatus", tag),
            None
        );
        assert_eq!(method_from_hyphenated_tag_id("gates-", tag), None);
        assert_eq!(
            method_from_hyphenated_tag_id("gates-checkStatus", None),
            None
        );
    }

    #[test]
    fn hoisted_request_fields_include_recursive_bases_in_fern_orders() {
        let primitive = TypeRef::Primitive(Prim::Str);
        let types = vec![
            TypeDecl::Object(ObjectType {
                reach_refs: Vec::new(),
                name: "GrandBase".to_string(),
                module: "grand_base".to_string(),
                bases: Vec::new(),
                fields: vec![
                    object_field("grand_optional", false, primitive.clone()),
                    object_field("grand_required", true, primitive.clone()),
                ],
                example_fields: std::collections::HashSet::new(),
                docstring: None,
                xml: None,
            }),
            TypeDecl::Object(ObjectType {
                reach_refs: Vec::new(),
                name: "Base".to_string(),
                module: "base".to_string(),
                bases: vec!["GrandBase".to_string()],
                fields: vec![
                    object_field("base_optional", false, primitive.clone()),
                    object_field("base_required", true, primitive.clone()),
                ],
                example_fields: std::collections::HashSet::new(),
                docstring: None,
                xml: None,
            }),
            TypeDecl::Object(ObjectType {
                reach_refs: Vec::new(),
                name: "Child".to_string(),
                module: "child".to_string(),
                bases: vec!["Base".to_string()],
                fields: vec![object_field("child", true, primitive)],
                example_fields: std::collections::HashSet::new(),
                docstring: None,
                xml: None,
            }),
        ];

        let fields = hoist_fields("Child", &types).expect("child object is present");
        assert_eq!(
            fields
                .iter()
                .map(|field| (field.wire_name.as_str(), field.reference_order))
                .collect::<Vec<_>>(),
            [
                ("child", 4),
                ("base_optional", 1),
                ("base_required", 0),
                ("grand_optional", 3),
                ("grand_required", 2),
            ]
        );
        assert!(fields
            .iter()
            .all(|field| { field.collision_prefix.as_deref() == Some("child") && !field.convert }));
        assert!(hoist_fields("Missing", &types).is_none());
    }

    #[test]
    fn discriminated_member_helpers_walk_nested_schemas_and_allof_bases() {
        let schemas: indexmap::IndexMap<String, Schema> =
            serde_json::from_value(serde_json::json!({
                "Base": {
                    "type": "object",
                    "required": ["baseValue"],
                    "properties": {
                        "kind": {"type": "string"},
                        "baseValue": {"type": "string", "enum": ["one", "two"]}
                    }
                },
                "Cat": {
                    "allOf": [
                        {"$ref": "#/components/schemas/Base"},
                        {
                            "type": "object",
                            "required": ["kind", "lives"],
                            "properties": {
                                "kind": {"type": "string", "enum": ["cat"]},
                                "lives": {"type": "integer", "example": 9}
                            }
                        }
                    ]
                },
                "Dog": {
                    "type": "object",
                    "required": ["kind"],
                    "properties": {
                        "kind": {"type": "string", "enum": ["dog"]},
                        "name": {"type": ["string", "null"], "readOnly": true},
                        "nodes": {"anyOf": [
                            {"type": "array", "items": {"$ref": "#/components/schemas/Bird"}},
                            {"type": "null"}
                        ]},
                        "effort": {"anyOf": [
                            {"type": "string", "enum": ["low", "high"]},
                            {"type": "null"}
                        ]},
                        "approvals": {"anyOf": [
                            {"type": "array", "items": {"oneOf": [
                                {"$ref": "#/components/schemas/Bird"},
                                {"$ref": "#/components/schemas/Fish"}
                            ]}},
                            {"type": "null"}
                        ]},
                        "env": {"anyOf": [
                            {"type": "object", "additionalProperties": {"type": "string"}},
                            {"type": "null"}
                        ]},
                        "child_nodes": {"anyOf": [
                            {"type": "array", "items": {
                                "type": "object", "properties": {"name": {"type": "string"}}
                            }},
                            {"type": "null"}
                        ]},
                        "direct_nodes": {
                            "type": "array", "nullable": true, "items": {
                                "type": "object", "properties": {"name": {"type": "string"}}
                            }
                        },
                        "direct_tools": {
                            "type": "array", "items": {"oneOf": [
                                {"$ref": "#/components/schemas/Bird"},
                                {"$ref": "#/components/schemas/Fish"}
                            ]}
                        },
                        "args": {
                            "type": "object", "nullable": true, "additionalProperties": {}
                        }
                    }
                },
                "Bird": {
                    "required": ["type"],
                    "properties": {"type": {"type": "string", "example": "bird"}}
                },
                "Fish": {
                    "required": ["type"],
                    "properties": {"type": {"type": "string", "example": "fish"}}
                },
                "Inferred": {
                    "oneOf": [
                        {"$ref": "#/components/schemas/Bird"},
                        {"$ref": "#/components/schemas/Fish"}
                    ]
                },
                "Envelope": {
                    "type": "object",
                    "properties": {
                        "payload": {
                            "oneOf": [
                                {"$ref": "#/components/schemas/Cat"},
                                {"$ref": "#/components/schemas/Dog"}
                            ],
                            "discriminator": {
                                "propertyName": "kind",
                                "mapping": {
                                    "cat": "#/components/schemas/Cat",
                                    "dog": "#/components/schemas/Dog"
                                }
                            }
                        }
                    }
                }
            }))
            .expect("schemas deserialize");

        let strips = discriminant_strips(&schemas, &std::collections::HashSet::new());
        assert_eq!(strips.get("Cat").map(String::as_str), Some("kind"));
        assert_eq!(strips.get("Dog").map(String::as_str), Some("kind"));
        assert_eq!(strips.get("Bird").map(String::as_str), Some("type"));
        assert_eq!(strips.get("Fish").map(String::as_str), Some("type"));

        // A union wrapper is flat and Fern writes the variant's own properties
        // before the ones its `allOf` base contributes, so `lives` precedes
        // `baseValue` even though `Base` is the first `allOf` member.
        let cat = member_fields(&schemas["Cat"], "kind", &schemas, Some("Cat"));
        assert_eq!(
            cat.iter()
                .map(|field| field.wire_name.as_str())
                .collect::<Vec<_>>(),
            ["lives", "baseValue"]
        );
        assert_eq!(cat[0].example.as_deref(), Some("9"));
        assert!(matches!(cat[1].type_ref, TypeRef::Named(ref name) if name == "BaseBaseValue"));

        let dog = member_fields(&schemas["Dog"], "kind", &schemas, Some("Dog"));
        assert_eq!(dog.len(), 9);
        assert_eq!(dog[0].wire_name, "name");
        assert!(dog[0].optional);
        assert!(dog[0].nullable);
        assert_eq!(
            dog[1].type_ref,
            TypeRef::List(Box::new(TypeRef::Named("Bird".to_string())))
        );
        assert_eq!(dog[2].type_ref, TypeRef::Named("DogEffort".to_string()));
        assert_eq!(
            dog[3].type_ref,
            TypeRef::List(Box::new(TypeRef::Named("DogApprovalsItem".to_string())))
        );
        assert_eq!(
            dog[4].type_ref,
            TypeRef::Dict(
                Box::new(TypeRef::Primitive(Prim::Str)),
                Box::new(TypeRef::Optional(Box::new(TypeRef::Primitive(Prim::Str))))
            )
        );
        assert_eq!(
            dog[5].type_ref,
            TypeRef::List(Box::new(TypeRef::Named("DogChildNodesItem".to_string())))
        );
        assert_eq!(
            dog[6].type_ref,
            TypeRef::List(Box::new(TypeRef::Named("DogDirectNodesItem".to_string())))
        );
        assert_eq!(
            dog[7].type_ref,
            TypeRef::List(Box::new(TypeRef::Named("DogDirectToolsItem".to_string())))
        );
        assert_eq!(
            dog[8].type_ref,
            TypeRef::Dict(
                Box::new(TypeRef::Primitive(Prim::Str)),
                Box::new(TypeRef::Primitive(Prim::Any))
            )
        );
    }

    #[test]
    fn explicit_message_unions_preserve_selected_optional_const_discriminants() {
        let doc: OpenApi = serde_json::from_value(serde_json::json!({
            "components": { "schemas": {
                "Approval": { "type": "object", "properties": {
                    "message_type": { "type": "string", "const": "approval" }
                } },
                "Assistant": { "type": "object", "required": ["message_type"], "properties": {
                    "message_type": { "type": "string", "const": "assistant_message" }
                } },
                "Result": { "type": "object", "required": ["message_type"], "properties": {
                    "message_type": { "type": "string", "const": "result_message" }
                } },
                "Messages": {
                    "oneOf": [
                        { "$ref": "#/components/schemas/Approval" },
                        { "$ref": "#/components/schemas/Assistant" }
                    ],
                    "discriminator": { "propertyName": "message_type", "mapping": {
                        "approval": "#/components/schemas/Approval",
                        "assistant_message": "#/components/schemas/Assistant"
                    } }
                }
            } },
            "paths": { "/results": { "get": { "responses": { "200": {
                "content": { "application/json": { "schema": { "oneOf": [
                    { "$ref": "#/components/schemas/Result" }
                ], "discriminator": { "propertyName": "message_type", "mapping": {
                    "result_message": "#/components/schemas/Result"
                } } } } }
            } } } } }
        }))
        .expect("message schemas deserialize");
        let strips = document_discriminant_strips(&doc);
        assert!(!strips.contains_key("Approval"));
        assert_eq!(
            strips.get("Assistant").map(String::as_str),
            Some("message_type")
        );
        assert_eq!(
            strips.get("Result").map(String::as_str),
            Some("message_type")
        );
    }

    #[test]
    fn error_body_hoisting_prefers_the_richest_shape_for_a_status() {
        let doc: OpenApi = serde_json::from_value(serde_json::json!({
            "paths": {
                "/first": { "get": { "responses": { "400": {
                    "content": { "application/json": { "schema": {
                        "type": "object", "properties": { "message": { "type": "string" } }
                    } } }
                } } } },
                "/second": { "get": { "responses": { "400": {
                    "content": { "application/json": { "schema": {
                        "type": "object", "properties": {
                            "message": { "type": "string" },
                            "errorCode": { "type": "string", "enum": ["invalid"] }
                        }
                    } } }
                } } } },
                "/third": { "get": { "responses": { "400": {
                    "content": { "application/json": { "schema": {
                        "type": "object", "properties": {
                            "message": { "type": "string" },
                            "errorCode": { "type": "string" }
                        }
                    } } }
                } } } }
            }
        }))
        .expect("error responses deserialize");
        let mut builder = Builder {
            types: Vec::new(),
            schemas: &doc.components.schemas,
            strip_discriminant: std::collections::HashMap::new(),
            building_types: std::collections::HashSet::new(),
            copying_refs: Vec::new(),
        };
        super::hoist_error_body_types(&doc, &mut builder);
        assert!(builder.types.iter().any(|decl| matches!(
            decl,
            TypeDecl::Object(object)
                if object.name == "BadRequestErrorBody"
                    && object.fields.len() == 2
                    && object.fields[1].type_ref == TypeRef::Primitive(Prim::Str)
        )));
        assert!(builder.types.iter().any(|decl| matches!(
            decl,
            TypeDecl::Enum(value) if value.name == "BadRequestErrorBodyErrorCode"
        )));
    }

    #[test]
    fn the_last_error_body_declaration_is_the_body_whole() {
        let doc: OpenApi = serde_json::from_value(serde_json::json!({
            "paths": {
                "/first": { "get": { "responses": { "500": {
                    "content": { "application/json": { "schema": {
                        "type": "object", "required": ["success", "error"],
                        "properties": {
                            "success": { "type": "boolean" },
                            "error": { "type": "string" }
                        }
                    } } }
                } } } },
                "/second": { "get": { "responses": { "500": {
                    "content": { "application/json": { "schema": {
                        "type": "object", "required": ["message"],
                        "properties": { "message": { "type": "string" } }
                    } } }
                } } } }
            }
        }))
        .expect("error responses deserialize");
        let mut builder = Builder {
            types: Vec::new(),
            schemas: &doc.components.schemas,
            strip_discriminant: std::collections::HashMap::new(),
            building_types: std::collections::HashSet::new(),
            copying_refs: Vec::new(),
        };
        super::hoist_error_body_types(&doc, &mut builder);
        let body = builder
            .types
            .iter()
            .find_map(|decl| match decl {
                TypeDecl::Object(object) if object.name == "InternalServerErrorBody" => {
                    Some(object)
                }
                _ => None,
            })
            .expect("the body is hoisted");
        let fields: Vec<(&str, bool)> = body
            .fields
            .iter()
            .map(|field| (field.wire_name.as_str(), field.optional))
            .collect();
        assert_eq!(fields, [("message", false)]);
    }

    #[test]
    fn an_inline_error_body_uses_its_body_model_however_the_response_is_reached() {
        let mut response: crate::openapi::Response = serde_json::from_value(serde_json::json!({
            "description": "Conflict",
            "content": { "application/json": { "schema": {
                "type": "object",
                "properties": { "message": { "type": "string" } }
            } } }
        }))
        .expect("response deserializes");
        assert_eq!(
            super::error_body_type(&response, "ConflictError"),
            TypeRef::Named("ConflictErrorBody".to_string())
        );
        assert_eq!(
            super::error_body_type(&response, "BadRequestError"),
            TypeRef::Named("BadRequestErrorBody".to_string())
        );
        // bunq's shared `GenericError` response: reached through a `$ref`, its
        // inline object is still the class's `BadRequestErrorBody`.
        response.reference = Some("#/components/responses/GenericError".to_string());
        assert_eq!(
            super::error_body_type(&response, "BadRequestError"),
            TypeRef::Named("BadRequestErrorBody".to_string())
        );
    }

    #[test]
    fn an_error_class_keeps_its_body_type_only_while_every_declaration_is_one_schema() {
        let error_bodies = |second: serde_json::Value| -> Vec<(String, TypeRef)> {
            let message = serde_json::json!({
                "type": "object",
                "properties": { "message": { "type": "string" } }
            });
            let ir = build_document(serde_json::json!({
                "openapi": "3.0.0",
                "info": { "title": "Nursery", "version": "1" },
                "paths": {
                    "/plants": { "get": { "operationId": "listPlants", "responses": {
                        "200": { "description": "ok" },
                        "404": { "description": "gone", "content": {
                            "application/json": { "schema": message.clone() }
                        } },
                        "5XX": { "description": "down", "content": {
                            "application/json": { "schema": message }
                        } }
                    } } },
                    "/seeds": { "get": { "operationId": "listSeeds", "responses": {
                        "200": { "description": "ok" },
                        "404": second
                    } } }
                }
            }));
            ir.errors
                .iter()
                .map(|error| (error.class_name.clone(), error.body_type.clone()))
                .collect()
        };
        let named = |name: &str| TypeRef::Named(name.to_string());
        // frankfurter's three `404`s are one shape, and the class is typed.
        assert_eq!(
            error_bodies(serde_json::json!({ "description": "also gone", "content": {
                "application/json": { "schema": {
                    "description": "Spelled differently, the same shape",
                    "type": "object",
                    "properties": { "message": { "type": "string", "example": "no" } }
                } }
            } })),
            [
                ("NotFoundError".to_string(), named("NotFoundErrorBody")),
                ("ServerError".to_string(), named("ServerErrorBody")),
            ]
        );
        // A property the first declaration lacks, a different property type, a
        // required property the first leaves optional, or no body at all is
        // another schema, and the class falls back to `typing.Any`.
        for second in [
            serde_json::json!({ "type": "object", "properties": {
                "message": { "type": "string" }, "code": { "type": "integer" }
            } }),
            serde_json::json!({ "type": "object", "properties": {
                "message": { "type": "integer" }
            } }),
            serde_json::json!({ "type": "object", "required": ["message"], "properties": {
                "message": { "type": "string" }
            } }),
        ] {
            assert_eq!(
                error_bodies(serde_json::json!({ "description": "other", "content": {
                    "application/json": { "schema": second.clone() }
                } }))[0],
                ("NotFoundError".to_string(), TypeRef::Primitive(Prim::Any)),
                "{second}"
            );
        }
        assert_eq!(
            error_bodies(serde_json::json!({ "description": "bodiless" }))[0],
            ("NotFoundError".to_string(), TypeRef::Primitive(Prim::Any))
        );
    }

    #[test]
    fn error_schema_equality_reads_the_converted_shape() {
        let schema = |value: serde_json::Value| -> Schema {
            serde_json::from_value(value).expect("schema deserializes")
        };
        let equal = |a: serde_json::Value, b: serde_json::Value| {
            super::error_schemas_equal(Some(&schema(a)), Some(&schema(b)))
        };
        let reference =
            |name: &str| serde_json::json!({ "$ref": format!("#/components/schemas/{name}") });
        assert!(equal(reference("Problem"), reference("Problem")));
        assert!(!equal(reference("Problem"), reference("Fault")));
        assert!(!equal(
            reference("Problem"),
            serde_json::json!({ "type": "object" })
        ));
        assert!(equal(
            serde_json::json!({ "allOf": [reference("Problem")] }),
            reference("Problem")
        ));
        assert!(equal(
            serde_json::json!({ "enum": ["a", "b"] }),
            serde_json::json!({ "type": "string", "enum": ["b", "a"] })
        ));
        assert!(!equal(
            serde_json::json!({ "enum": ["a"] }),
            serde_json::json!({ "enum": ["a", "b"] })
        ));
        assert!(equal(
            serde_json::json!({ "type": "array", "items": { "type": "string" } }),
            serde_json::json!({ "type": "array", "items": { "type": "string" } })
        ));
        assert!(!equal(
            serde_json::json!({ "type": "array", "items": { "type": "string" } }),
            serde_json::json!({ "type": "array", "items": { "type": "integer" } })
        ));
        assert!(equal(
            serde_json::json!({ "type": "object", "additionalProperties": { "type": "string" } }),
            serde_json::json!({ "additionalProperties": { "type": "string" } })
        ));
        assert!(!equal(
            serde_json::json!({ "type": "string" }),
            serde_json::json!({ "type": "string", "nullable": true })
        ));
        assert!(equal(
            serde_json::json!({ "oneOf": [reference("A"), { "type": "string" }] }),
            serde_json::json!({ "anyOf": [reference("A"), { "type": "string" }] })
        ));
        assert!(!equal(
            serde_json::json!({ "oneOf": [reference("A"), reference("B")] }),
            serde_json::json!({ "oneOf": [reference("B"), reference("A")] })
        ));
        // A composition compares its own and its inline members' properties;
        // the `$ref` bases it extends are not compared.
        assert!(equal(
            serde_json::json!({ "allOf": [reference("Base"), { "properties": {
                "detail": { "type": "string" }
            } }] }),
            serde_json::json!({ "allOf": [reference("Other"), reference("More")],
                "properties": { "detail": { "type": "string" } } })
        ));
        assert!(super::error_schemas_equal(
            None,
            Some(&schema(serde_json::json!({})))
        ));
        assert!(!super::error_schemas_equal(
            None,
            Some(&schema(serde_json::json!({ "type": "string" })))
        ));
    }

