    #[test]
    fn oauth2_scopes_emit_oauth_scope_enum() {
        let doc: crate::openapi::OpenApi = serde_json::from_value(serde_json::json!({
            "components": {
                "securitySchemes": {
                    "oauth2": {
                        "type": "oauth2",
                        "flows": {
                            "authorizationCode": {
                                "authorizationUrl": "https://example.com/auth",
                                "tokenUrl": "https://example.com/token",
                                "scopes": {
                                    "Public": "",
                                    "ReadData": "Read data",
                                    "WriteData": "Write data"
                                }
                            }
                        }
                    }
                }
            }
        }))
        .expect("document deserializes");
        let enum_type = oauth_scope_enum(&doc).expect("oauth scopes produce enum");
        assert_eq!(enum_type.name, "OauthScope");
        assert_eq!(
            enum_type
                .members
                .iter()
                .map(|m| (m.name.as_str(), m.value.as_str(), m.docstring.as_deref()))
                .collect::<Vec<_>>(),
            [
                ("PUBLIC", "Public", Some("")),
                ("READ_DATA", "ReadData", Some("Read data")),
                ("WRITE_DATA", "WriteData", Some("Write data")),
            ]
        );
    }

    #[test]
    fn bare_object_map_values_are_open_dicts() {
        let schema: Schema = serde_json::from_value(serde_json::json!({
            "type": "object",
            "additionalProperties": { "type": "object" }
        }))
        .expect("schema deserializes");
        assert!(matches!(
            base_type_ref(&schema),
            TypeRef::Dict(_, ref value)
                if matches!(
                    &**value,
                    TypeRef::Dict(_, inner)
                        if matches!(&**inner, TypeRef::Primitive(Prim::Any))
                )
        ));
    }

    #[test]
    fn bare_objects_are_open_dicts() {
        let schema: Schema = serde_json::from_value(serde_json::json!({ "type": "object" }))
            .expect("schema deserializes");
        assert!(matches!(
            base_type_ref(&schema),
            TypeRef::Dict(_, ref value)
                if matches!(&**value, TypeRef::Primitive(Prim::Any))
        ));
    }

    fn scalar(ty: &str, format: Option<&str>) -> Option<(TypeRef, bool)> {
        let schema = Schema {
            ty: Some(TypeField::Single(ty.to_string())),
            format: format.map(str::to_string),
            ..Schema::default()
        };
        scalar_body(&schema)
    }

    #[test]
    fn scalar_body_maps_primitives_and_flags_uuid_and_byte_content_type() {
        // Plain scalars and the date formats serialize with no content-type header.
        assert!(matches!(
            scalar("string", None),
            Some((TypeRef::Primitive(Prim::Str), false))
        ));
        assert!(matches!(
            scalar("string", Some("date-time")),
            Some((TypeRef::Primitive(Prim::Datetime), false))
        ));
        assert!(matches!(
            scalar("integer", None),
            Some((TypeRef::Primitive(Prim::Int), false))
        ));
        assert!(matches!(
            scalar("boolean", None),
            Some((TypeRef::Primitive(Prim::Bool), false))
        ));
        // `uuid`/`byte` render as `str` but carry the content-type header.
        assert!(matches!(
            scalar("string", Some("uuid")),
            Some((TypeRef::Primitive(Prim::Str), true))
        ));
        assert!(matches!(
            scalar("string", Some("byte")),
            Some((TypeRef::Primitive(Prim::Str), true))
        ));
        // So do the formats Fern types; any other string format is a plain
        // `str` (the hand-written fixture `format-scalar-bodies`).
        for format in ["email", "hostname", "ipv4", "password", "uri"] {
            assert!(matches!(
                scalar("string", Some(format)),
                Some((TypeRef::Primitive(Prim::Str), true))
            ));
        }
        for format in ["duration", "time", "uri-template", "custom-thing"] {
            assert!(matches!(
                scalar("string", Some(format)),
                Some((TypeRef::Primitive(Prim::Str), false))
            ));
        }
        // An inline JSON binary string stays a bytes-typed JSON payload.
        assert!(matches!(
            scalar("string", Some("binary")),
            Some((TypeRef::Primitive(Prim::Bytes), true))
        ));
        // Non-scalar shapes use their dedicated dispatch.
        assert!(scalar("object", None).is_none());
        assert!(scalar("array", None).is_none());
    }

    #[test]
    fn method_name_snakes_whole_id_for_multi_segment_groups() {
        // The group prefix (`warehouse_bins`) is multi-segment, so the whole
        // operationId is snake-cased.
        assert_eq!(
            method_from_grouped_id("warehouse_bins_add"),
            "warehouse_bins_add"
        );
        assert_eq!(
            method_from_grouped_id("warehouse_routes_fetchMixedCase"),
            "warehouse_routes_fetch_mixed_case"
        );
        assert_eq!(
            method_from_grouped_id("warehouse_loadingBays_findSlot"),
            "warehouse_loading_bays_find_slot"
        );
    }

    #[test]
    fn method_name_lowercases_suffix_for_single_segment_groups() {
        // A single-segment group (`weighStation`) contributes nothing to the method
        // name; only the suffix survives, flattened to lowercase.
        assert_eq!(
            method_from_grouped_id("weighStation_recordWithoutPayload"),
            "recordwithoutpayload"
        );
        assert_eq!(
            method_from_grouped_id("parcelRouting_dispatchWithReceipt"),
            "dispatchwithreceipt"
        );
    }

    #[test]
    fn module_mirrors_the_group_naming() {
        assert_eq!(
            module_from_grouped_id("warehouse_bins_add"),
            "warehouse_bins"
        );
        assert_eq!(
            module_from_grouped_id("warehouse_loadingBays_findSlot"),
            "warehouse_loading_bays"
        );
        assert_eq!(
            module_from_grouped_id("weighStation_recordWithoutPayload"),
            "weighstation"
        );
    }

    fn op(operation_id: &str, tag: &str) -> crate::openapi::Operation {
        serde_json::from_value(serde_json::json!({
            "operationId": operation_id,
            "tags": [tag],
        }))
        .expect("operation deserializes from operationId + tag")
    }

    #[test]
    fn tag_wins_over_a_verb_prefix_operationid() {
        use super::{endpoint_method_name, endpoint_module};
        // bunq: the operationId is `VERB_Resource` with an underscore, but the prefix
        // (`create`) is not the tag (`attachment-public`). Fern groups by the tag and
        // keeps the whole id, snake-cased, as the method.
        let o = op("CREATE_AttachmentPublic", "attachment-public");
        assert_eq!(
            endpoint_module(&o, "/attachment-public"),
            "attachment_public"
        );
        assert_eq!(
            endpoint_method_name(&o, "POST", "/attachment-public"),
            "create_attachment_public"
        );
        // A multi-word tag with hyphens still maps cleanly.
        let o = op("List_all_Content_for_AttachmentPublic", "content");
        assert_eq!(endpoint_module(&o, "/x"), "content");
        assert_eq!(
            endpoint_method_name(&o, "GET", "/x"),
            "list_all_content_for_attachment_public"
        );
    }

    #[test]
    fn operationid_prefix_that_is_the_tag_still_groups_by_the_prefix() {
        use super::{endpoint_method_name, endpoint_module};
        // When the operationId prefix is the tag, grouping and method-stripping
        // agree.
        let o = op("parcelRouting_dispatchWithReceipt", "ParcelRouting");
        assert_eq!(endpoint_module(&o, "/x"), "parcelrouting");
        assert_eq!(
            endpoint_method_name(&o, "POST", "/x"),
            "dispatchwithreceipt"
        );
        let o = op("warehouse_labels_fetchLabelBatch", "WarehouseLabels");
        assert_eq!(endpoint_module(&o, "/x"), "warehouse_labels");
        assert_eq!(
            endpoint_method_name(&o, "GET", "/x"),
            "warehouse_labels_fetch_label_batch"
        );

        // A lowercase tag does not infer camel-case word boundaries it did not
        // declare: Otoroshi keeps both operations in `apikeys` and retains the
        // full `api_keys...` method name.
        let o = op("apiKeysFromGroup", "apikeys");
        assert_eq!(endpoint_module(&o, "/x"), "apikeys");
        assert_eq!(endpoint_method_name(&o, "GET", "/x"), "api_keys_from_group");
        let o = op("apiKeys", "apikeys");
        assert_eq!(endpoint_module(&o, "/x"), "apikeys");
        assert_eq!(endpoint_method_name(&o, "GET", "/x"), "api_keys");

        let o = op("CatalogInfo", "Catalog");
        assert_eq!(endpoint_module(&o, "/v2/catalog/info"), "catalog");
        assert_eq!(
            endpoint_method_name(&o, "GET", "/v2/catalog/info"),
            "catalog_info"
        );
    }

    #[test]
    fn a_declared_group_needs_a_method_name_and_keeps_leading_underscores() {
        use super::endpoint_module;
        let operation = |value: serde_json::Value| -> crate::openapi::Operation {
            serde_json::from_value(value).expect("operation deserializes")
        };
        let o = operation(serde_json::json!({
            "operationId": "callCar",
            "x-fern-sdk-group-name": ["_lift", "_staff"],
            "x-fern-sdk-method-name": "summon",
        }));
        assert_eq!(endpoint_module(&o, "/x"), "_lift/_staff");
        let o = operation(serde_json::json!({
            "operationId": "ringBell",
            "x-crozier-sdk-group-name": "__lobby",
            "x-crozier-sdk-method-name": "ring",
        }));
        assert_eq!(endpoint_module(&o, "/x"), "__lobby");
        // Without a method name the group is ignored: untagged is the root
        // client, tagged is the tag's.
        let o = operation(serde_json::json!({
            "operationId": "listHoists",
            "x-fern-sdk-group-name": ["harbor", "hoists"],
        }));
        assert_eq!(endpoint_module(&o, "/x"), "");
        let o = operation(serde_json::json!({
            "operationId": "listTugs",
            "tags": ["Docks"],
            "x-crozier-sdk-group-name": "marina",
        }));
        assert_eq!(endpoint_module(&o, "/x"), "docks");
    }

    #[test]
    fn a_prefix_groups_only_when_its_words_are_the_tags_words() {
        use super::{endpoint_method_name, endpoint_module};
        // An all-capitals tag spelled letter for letter by a split prefix keeps
        // the tag as the module and the whole id as the method.
        let o = op("q_x_schedule", "QX");
        assert_eq!(endpoint_module(&o, "/x"), "qx");
        assert_eq!(endpoint_method_name(&o, "GET", "/x"), "q_x_schedule");
        let o = op("parcelRouting_dispatch", "Parcel-Routing");
        assert_eq!(endpoint_module(&o, "/x"), "parcel_routing");
        assert_eq!(
            endpoint_method_name(&o, "GET", "/x"),
            "parcel_routing_dispatch"
        );
        // Word for word, the prefix is the group.
        let o = op("documents_documenttype_get", "Documents/DocumentType");
        assert_eq!(endpoint_module(&o, "/x"), "documents_documenttype");
        assert_eq!(endpoint_method_name(&o, "GET", "/x"), "get");
        let o = op("warehouse_labels_get", "warehouseLabels");
        assert_eq!(endpoint_module(&o, "/x"), "warehouse_labels");
        assert_eq!(endpoint_method_name(&o, "GET", "/x"), "get");
    }

    #[test]
    fn a_tag_only_operationid_is_a_root_method_named_for_the_tag() {
        use super::{endpoint_method_name, endpoint_module, module_title};
        // The authored probe `376-357-tag-only-operation-id`: Fern hoists a
        // lone `Search_` under `Search` to the root client as `search`, where the
        // `group_method` split would leave an empty method in a `search` client.
        let doc: OpenApi = serde_json::from_value(serde_json::json!({
            "openapi": "3.0.3", "info": { "title": "t", "version": "1" }, "paths": {}
        }))
        .unwrap();
        let o = op("Search_", "Search");
        assert_eq!(endpoint_module(&o, "/search"), "");
        assert_eq!(endpoint_method_name(&o, "GET", "/search"), "search");
        assert_eq!(
            module_title(&doc, &o, "/search"),
            module_title(&doc, &op("Search", "Search"), "/search")
        );
        // Only the tag's own spelling before one `_` reads that way: another
        // prefix keeps its `group_method` split, and a second `_` is no tag.
        let o = op("Find_", "Search");
        assert_eq!(endpoint_module(&o, "/search"), "search");
        let o = op("Search__", "Search");
        assert_eq!(endpoint_module(&o, "/search"), "search");
    }

    #[test]
    fn dotted_operationids_strip_the_group_and_keep_flat_method_names() {
        use super::{endpoint_method_name, endpoint_module, module_title};

        let doc: OpenApi =
            serde_json::from_value(serde_json::json!({})).expect("empty document deserializes");
        let o = op("App.GetApplicationApiUsage", "App");
        assert_eq!(endpoint_module(&o, "/App/ApiUsage/{applicationId}/"), "app");
        assert_eq!(
            module_title(&doc, &o, "/App/ApiUsage/{applicationId}/"),
            "App"
        );
        assert_eq!(
            endpoint_method_name(&o, "GET", "/App/ApiUsage/{applicationId}/"),
            "getapplicationapiusage"
        );

        let o = op(
            "clientSideAccessTokens.createClientSideAccessToken",
            "clientSideAccessTokens",
        );
        assert_eq!(
            endpoint_module(&o, "/v1/client-side-access-tokens"),
            "client_side_access_tokens"
        );
        assert_eq!(
            endpoint_method_name(&o, "POST", "/v1/client-side-access-tokens"),
            "client_side_access_tokens_create_client_side_access_token"
        );

        let o = op("CommunityContent.GetCommunityContent", "CommunityContent");
        assert_eq!(
            endpoint_module(&o, "/CommunityContent/Get/"),
            "communitycontent"
        );
        assert_eq!(
            endpoint_method_name(&o, "GET", "/CommunityContent/Get/"),
            "getcommunitycontent"
        );

        let o: crate::openapi::Operation = serde_json::from_value(serde_json::json!({
            "operationId": ".GetAvailableLocales",
        }))
        .expect("operation deserializes");
        assert_eq!(endpoint_module(&o, "/GetAvailableLocales/"), "_");
        assert_eq!(module_title(&doc, &o, "/GetAvailableLocales/"), "");
        assert_eq!(
            endpoint_method_name(&o, "GET", "/GetAvailableLocales/"),
            "getavailablelocales"
        );
    }

    #[test]
    fn a_dotted_group_that_is_its_tags_one_word_is_stripped() {
        use super::{endpoint_method_name, endpoint_module, module_title};
        let undeclared: OpenApi =
            serde_json::from_value(serde_json::json!({})).expect("empty document deserializes");
        // Kompaz: the PascalCase tag is one word to Fern, the dotted group's.
        let o = op("organizationLogo.show", "OrganizationLogo");
        assert_eq!(endpoint_module(&o, "/x"), "organizationlogo");
        assert_eq!(endpoint_method_name(&o, "GET", "/x"), "show");
        assert_eq!(module_title(&undeclared, &o, "/x"), "Organizationlogo");
        let o = op("organizationLogo.destroyAll", "organizationlogo");
        assert_eq!(endpoint_method_name(&o, "DELETE", "/x"), "destroyall");
        // A declared tag keeps its spelling as the title.
        let declared: OpenApi = serde_json::from_value(serde_json::json!({
            "tags": [{"name": "ProjectIcon"}],
        }))
        .expect("document with tags deserializes");
        let o = op("projectIcon.show", "ProjectIcon");
        assert_eq!(endpoint_method_name(&o, "GET", "/x"), "show");
        assert_eq!(module_title(&declared, &o, "/x"), "ProjectIcon");
        // A camelCase tag is two words, so letta's group keeps its whole id.
        let o = op(
            "scheduledMessages.listScheduledMessages",
            "scheduledMessages",
        );
        assert_eq!(endpoint_module(&o, "/x"), "scheduled_messages");
        assert_eq!(
            endpoint_method_name(&o, "GET", "/x"),
            "scheduled_messages_list_scheduled_messages"
        );
        // A group that is not the tag leaves the PascalCase tag snake-cased.
        let o = op("fooBar.show", "SiteCover");
        assert_eq!(endpoint_module(&o, "/x"), "site_cover");
        assert_eq!(endpoint_method_name(&o, "GET", "/x"), "foo_bar_show");
        assert_eq!(module_title(&undeclared, &o, "/x"), "SiteCover");
        let o = op("organizationLogo.show", "Organization");
        assert_eq!(endpoint_module(&o, "/x"), "organization");
        assert_eq!(
            endpoint_method_name(&o, "GET", "/x"),
            "organization_logo_show"
        );
    }

