    #[test]
    fn inline_maps_hoist_multi_alternative_value_aliases() {
        let map = serde_json::json!({"type": "object", "additionalProperties": {
            "anyOf": [
                {"type": "string"}, {"type": "number"},
                {"type": "array", "items": {"type": "string"}},
                {"type": "object", "additionalProperties": {"type": "string"}}
            ]
        }});
        let ir = build_document(serde_json::json!({
            "openapi": "3.0.3", "info": {"title": "Records", "version": "1"},
            "paths": {"/records": {"post": {
                "operationId": "createRecord", "tags": ["records"],
                "requestBody": {"required": true, "content": {"application/json": {
                    "schema": {"type": "object", "required": ["values"], "properties": {
                        "values": map.clone(),
                        "optional_values": {"type": "object", "additionalProperties": {
                            "anyOf": [{"type": "string"}, {"type": "null"}]
                        }}
                    }}
                }}},
                "responses": {"200": {"description": "Stored", "content": {"application/json": {
                    "schema": {"type": "object", "properties": {"values": map}}
                }}}}
            }}}
        }));
        let declarations: Vec<_> = ir
            .types
            .iter()
            .chain(ir.tag_types.iter().map(|tag| &tag.decl))
            .collect();
        for name in [
            "CreateRecordRequestValuesValue",
            "CreateRecordResponseValuesValue",
        ] {
            let alias = declarations
                .iter()
                .find_map(|decl| match decl {
                    TypeDecl::Alias(alias) if alias.name == name => Some(alias),
                    _ => None,
                })
                .unwrap_or_else(|| panic!("map value alias {name} was not hoisted"));
            assert_eq!(
                alias.target,
                TypeRef::Union(vec![
                    TypeRef::Primitive(Prim::Str),
                    TypeRef::Primitive(Prim::Float),
                    TypeRef::List(Box::new(TypeRef::Primitive(Prim::Str))),
                    TypeRef::Dict(
                        Box::new(TypeRef::Primitive(Prim::Str)),
                        Box::new(TypeRef::Primitive(Prim::Str))
                    )
                ])
            );
        }
        assert!(!declarations
            .iter()
            .any(|decl| decl.name() == "CreateRecordRequestOptionalValuesValue"));
    }

    #[test]
    fn inline_hoister_handles_enum_array_shapes_and_defensive_inputs() {
        let mut hoister = InlineHoister {
            copying_refs: Vec::new(),
            root_types: &[],
            schemas: None,
            out: Vec::new(),
        };
        for invalid in [
            schema(serde_json::json!({ "type": "string" })),
            schema(serde_json::json!({ "type": "array" })),
            schema(serde_json::json!({
                "type": "array", "items": { "$ref": "#/components/schemas/Kind" }
            })),
            schema(serde_json::json!({
                "type": "array", "items": { "type": "string" }
            })),
        ] {
            assert!(hoister.hoist_array_item_enum("Choice", &invalid).is_none());
        }
        let list = schema(serde_json::json!({
            "type": "array",
            "items": { "type": "string", "enum": ["a", "b"] }
        }));
        assert_eq!(
            hoister.hoist_array_item_enum("Choice", &list),
            Some(TypeRef::List(Box::new(TypeRef::Named(
                "ChoiceItem".to_string()
            ))))
        );
        let unique = schema(serde_json::json!({
            "type": "array", "uniqueItems": true,
            "items": { "type": "string", "enum": ["x"] }
        }));
        assert_eq!(
            hoister.hoist_array_item_enum("Unique", &unique),
            Some(TypeRef::List(Box::new(TypeRef::Named(
                "UniqueItem".to_string()
            ))))
        );
        assert_eq!(hoister.out.len(), 2);

        let nullable_string = schema(serde_json::json!({
            "anyOf": [{ "type": "string" }, { "type": "null" }]
        }));
        assert_eq!(
            hoister.prop_type_ref("CreateAgentRequest", "name", &nullable_string),
            TypeRef::Primitive(Prim::Str)
        );
        let nullable_array = schema(serde_json::json!({
            "anyOf": [
                { "type": "array", "items": { "type": "string" } },
                { "type": "null" }
            ]
        }));
        assert_eq!(
            hoister.prop_type_ref("CreateAgentRequest", "tags", &nullable_array),
            TypeRef::List(Box::new(TypeRef::Primitive(Prim::Str)))
        );
        let nullable_map = schema(serde_json::json!({
            "anyOf": [
                { "type": "object", "additionalProperties": true },
                { "type": "null" }
            ]
        }));
        assert_eq!(
            hoister.prop_type_ref("CreateAgentRequest", "metadata", &nullable_map),
            TypeRef::Dict(
                Box::new(TypeRef::Primitive(Prim::Str)),
                Box::new(TypeRef::Primitive(Prim::Any)),
            )
        );
        let nullable_reference = schema(serde_json::json!({
            "anyOf": [
                { "$ref": "#/components/schemas/StopReasonType" },
                { "type": "null" }
            ]
        }));
        assert_eq!(
            hoister.prop_type_ref(
                "CreateAgentRequest",
                "last_stop_reason",
                &nullable_reference,
            ),
            TypeRef::Named("StopReasonType".to_string())
        );
        let nullable_enum = schema(serde_json::json!({
            "anyOf": [
                { "type": "string", "enum": ["low", "high"] },
                { "type": "null" }
            ]
        }));
        assert_eq!(
            hoister.prop_type_ref("CreateAgentRequest", "effort", &nullable_enum),
            TypeRef::Named("CreateAgentRequestEffort".to_string())
        );
        assert!(hoister.out.iter().any(|declaration| matches!(
            declaration,
            TypeDecl::Enum(enumeration) if enumeration.name == "CreateAgentRequestEffort"
        )));
        assert_eq!(
            hoister.hoist_param_enum("ListAgentsRequest", "name", &nullable_string),
            TypeRef::Optional(Box::new(TypeRef::Primitive(Prim::Str)))
        );
        assert_eq!(
            hoister.hoist_param_enum("ListAgentsRequest", "tags", &nullable_array),
            TypeRef::Optional(Box::new(TypeRef::List(Box::new(TypeRef::Primitive(
                Prim::Str
            )))))
        );
        assert_eq!(
            hoister.hoist_param_enum("ListAgentsRequest", "last_stop_reason", &nullable_reference,),
            TypeRef::Optional(Box::new(TypeRef::Named("StopReasonType".to_string())))
        );

        let offset = schema(serde_json::json!({
            "oneOf": [{ "type": "string" }, { "type": "number" }]
        }));
        assert_eq!(
            hoister.hoist_param_enum("FeedsListFeedsRequest", "offset", &offset),
            TypeRef::Named("FeedsListFeedsRequestOffset".to_string())
        );
        let operator = schema(serde_json::json!({
            "anyOf": [
                { "type": "string", "enum": ["gt", "lt"] },
                { "type": "null" }
            ]
        }));
        assert_eq!(
            hoister.hoist_param_enum("ListRunsRequest", "duration_operator", &operator),
            TypeRef::Optional(Box::new(TypeRef::Named(
                "ListRunsRequestDurationOperator".to_string()
            )))
        );
        assert!(hoister.out.iter().any(|decl| matches!(
            decl,
            TypeDecl::Alias(alias) if alias.name == "FeedsListFeedsRequestOffset"
        )));
        // A union alias converts wherever its annotation is what Fern serializes
        // against; a query parameter carrying one applies its own scalar guard,
        // which is what leaves `offset` written raw onto the URL.
        assert!(super::type_needs_convert(
            &TypeRef::Named("FeedsListFeedsRequestOffset".to_string()),
            &hoister.out
        ));
        assert!(hoister
            .reaches_url_as_scalars(&TypeRef::Named("FeedsListFeedsRequestOffset".to_string())));
        let unknown_union = TypeDecl::Alias(AliasType {
            constraints: None,
            reach_refs: Vec::new(),
            name: "UnknownUnion".to_string(),
            module: "unknown_union".to_string(),
            target: TypeRef::Union(vec![TypeRef::Primitive(Prim::Any)]),
            docstring: None,
            min_length: None,
            max_length: None,
        });
        assert!(super::type_needs_convert(
            &TypeRef::Named("UnknownUnion".to_string()),
            &[unknown_union]
        ));
        assert!(hoister.out.iter().any(|decl| matches!(
            decl,
            TypeDecl::Enum(value) if value.name == "ListRunsRequestDurationOperator"
        )));
    }

    #[test]
    fn request_body_hoists_inferred_discriminated_component_union() {
        let doc: OpenApi = serde_json::from_value(serde_json::json!({
            "components": { "schemas": {
                "UserUpdate": {
                    "type": "object", "properties": {
                        "message_type": { "type": "string", "const": "user_message", "default": "user_message" },
                        "content": { "type": "string" }
                    }
                },
                "AssistantUpdate": {
                    "type": "object", "properties": {
                        "message_type": { "type": "string", "const": "assistant_message", "default": "assistant_message" },
                        "content": { "type": "string" }
                    }
                }
            } }
        }))
        .expect("components deserialize");
        let body: crate::openapi::RequestBody = serde_json::from_value(serde_json::json!({
            "required": true,
            "content": { "application/json": { "schema": { "anyOf": [
                { "$ref": "#/components/schemas/UserUpdate" },
                { "$ref": "#/components/schemas/AssistantUpdate" }
            ] } } }
        }))
        .expect("request body deserializes");
        let mut hoister = InlineHoister {
            copying_refs: Vec::new(),
            root_types: &[],
            schemas: Some(&doc.components.schemas),
            out: Vec::new(),
        };
        let resolved = super::resolve_request_body(
            &doc,
            &[],
            &body,
            &mut hoister,
            "ModifyMessageRequest",
            false,
        );
        assert!(matches!(resolved, Some(RequestBody::Single(_))));
        assert!(hoister.out.iter().any(|declaration| matches!(
            declaration,
            TypeDecl::DiscriminatedUnion(union)
                if union.name == "ModifyMessageRequest"
                    && union.discriminant_property == "message_type"
        )));
    }

    #[test]
    fn endpoint_hoists_inferred_discriminated_response_union() {
        let doc: OpenApi = serde_json::from_value(serde_json::json!({
            "components": { "schemas": {
                "UserMessage": {
                    "type": "object", "properties": {
                        "message_type": { "type": "string", "const": "user_message", "default": "user_message" },
                        "content": { "type": "string" }
                    }
                },
                "AssistantMessage": {
                    "type": "object", "properties": {
                        "message_type": { "type": "string", "const": "assistant_message", "default": "assistant_message" },
                        "content": { "type": "string" }
                    }
                }
            } },
            "paths": { "/messages": { "get": {
                "tags": ["messages"], "operationId": "messages.list",
                "responses": { "200": { "description": "ok", "content": {
                    "application/json": { "schema": { "oneOf": [
                        { "$ref": "#/components/schemas/UserMessage" },
                        { "$ref": "#/components/schemas/AssistantMessage" }
                    ], "discriminator": { "propertyName": "message_type", "mapping": {
                        "user_message": "#/components/schemas/UserMessage",
                        "assistant_message": "#/components/schemas/AssistantMessage"
                    } } } }
                } } }
            } } }
        }))
        .expect("document deserializes");
        let (_, operation) = doc.paths["/messages"]
            .operations()
            .into_iter()
            .next()
            .expect("GET operation exists");
        let mut tag_types = Vec::new();
        let endpoint = super::build_endpoint(
            &doc,
            &[],
            "/messages",
            "GET",
            operation,
            &mut tag_types,
            &std::collections::HashSet::new(),
        );
        assert_eq!(
            endpoint.response,
            Some(TypeRef::Named("MessagesListResponse".to_string()))
        );
        assert!(
            tag_types.iter().any(|tag| matches!(
                &tag.decl,
                TypeDecl::DiscriminatedUnion(union)
                    if union.name == "MessagesListResponse"
                        && union.discriminant_property == "message_type"
            )),
            "{tag_types:?}"
        );

        let array = schema(serde_json::json!({
            "type": "array", "items": {
                "oneOf": [
                    { "$ref": "#/components/schemas/UserMessage" },
                    { "$ref": "#/components/schemas/AssistantMessage" }
                ],
                "discriminator": { "propertyName": "message_type", "mapping": {
                    "user_message": "#/components/schemas/UserMessage",
                    "assistant_message": "#/components/schemas/AssistantMessage"
                } }
            }
        }));
        let mut hoister = InlineHoister {
            copying_refs: Vec::new(),
            root_types: &[],
            schemas: Some(&doc.components.schemas),
            out: Vec::new(),
        };
        assert_eq!(
            hoister.hoist_response_array_item_union("MessagesResponseItem", &array),
            Some(TypeRef::List(Box::new(TypeRef::Named(
                "MessagesResponseItem".to_string()
            ))))
        );
        assert!(hoister.out.iter().any(|declaration| matches!(
            declaration,
            TypeDecl::DiscriminatedUnion(union) if union.name == "MessagesResponseItem"
        )));
    }

    /// Fern's flat tree pages a paginated operation as its packaged tree does
    /// (`beacon-registry-pages-flat`, `crane-hire-cursor-flat`,
    /// `ledger-records-offset-flat`; measured at Fern CLI 5.163.1 with
    /// fern-python-sdk 5.41.3).
    #[test]
    fn the_flat_layout_keeps_an_operations_pagination() {
        let doc = crate::openapi::load(
            &std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("docs/openapi-surface/handwritten/beacon-registry-pages/openapi.yml"),
        )
        .unwrap();
        let mut config = crate::config::GenerateConfig::new(
            std::path::PathBuf::from("openapi.yml"),
            std::path::PathBuf::from("out"),
            Some("api".into()),
            None,
            None,
            crate::settings::ExtraFields::default(),
            "Beacons",
        )
        .unwrap();
        config.layout = crate::settings::Layout::Flat;
        let ir = super::build(&doc, &config);
        let endpoint = ir
            .endpoints
            .iter()
            .find(|endpoint| endpoint.method_name == "list_beacons")
            .expect("the paginated operation is an endpoint");
        assert!(endpoint.pagination.is_some());
    }

    /// The `dormant-sensor-unions` fixture (Fern CLI 5.163.1, fern-python-sdk
    /// 5.41.3): a lone inline string-enum alternative is the enum itself, as a
    /// component (`Pitch`, `Tone`) and as a property (`Reading.mode`), with the
    /// alternative's own description and no `…Zero` class; a union of only
    /// `null`s is `Optional[Any]`.
    #[test]
    fn dormant_sensor_unions_declare_lone_enum_alternatives_as_the_enum() {
        let doc = crate::openapi::load(
            &std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("docs/openapi-surface/handwritten/dormant-sensor-unions/openapi.yml"),
        )
        .unwrap();
        let config = crate::config::GenerateConfig::new(
            std::path::PathBuf::from("openapi.yml"),
            std::path::PathBuf::from("out"),
            Some("fern".into()),
            None,
            None,
            crate::settings::ExtraFields::default(),
            "Dormant Sensors",
        )
        .unwrap();
        let ir = super::build(&doc, &config);
        let enumerated = |name: &str| {
            ir.types.iter().find_map(|decl| match decl {
                TypeDecl::Enum(declaration) if declaration.name == name => Some(declaration),
                _ => None,
            })
        };
        let pitch = enumerated("Pitch").expect("Pitch is an enum");
        assert_eq!(pitch.docstring, None);
        assert_eq!(
            enumerated("Tone").and_then(|tone| tone.docstring.as_deref()),
            Some("How the sensor's alarm sounds.")
        );
        assert!(enumerated("ReadingMode").is_some());
        for hoisted in ["PitchZero", "ToneZero", "ReadingModeZero"] {
            assert!(
                !ir.types.iter().any(|decl| decl.name() == hoisted),
                "{hoisted}"
            );
        }
        let silence = ir.types.iter().find_map(|decl| match decl {
            TypeDecl::Alias(alias) if alias.name == "Silence" => Some(&alias.target),
            _ => None,
        });
        assert_eq!(
            silence,
            Some(&TypeRef::Optional(Box::new(TypeRef::Primitive(Prim::Any))))
        );
    }

    #[test]
    fn lone_inline_string_enum_reads_only_a_bare_single_enum_alternative() {
        let lone =
            |value: serde_json::Value| super::lone_inline_string_enum(&schema(value)).is_some();
        let pair = serde_json::json!({"type": "string", "enum": ["low", "high"]});
        assert!(lone(serde_json::json!({"anyOf": [pair]})));
        assert!(lone(
            serde_json::json!({"oneOf": [pair], "description": "Dropped."})
        ));
        for kept in [
            serde_json::json!({"anyOf": [pair, {"type": "integer"}]}),
            serde_json::json!({"anyOf": [{"type": "string"}]}),
            serde_json::json!({"anyOf": [{"type": "string", "const": "low"}]}),
            serde_json::json!({"anyOf": [{"type": "integer", "enum": [1, 2]}]}),
            serde_json::json!({"type": "string", "anyOf": [pair]}),
            serde_json::json!({"nullable": true, "anyOf": [pair]}),
            serde_json::json!({"oneOf": [pair], "anyOf": [pair]}),
            serde_json::json!({"anyOf": [{"$ref": "#/components/schemas/Pitch"}]}),
        ] {
            assert!(!lone(kept.clone()), "{kept}");
        }
    }

    #[test]
    fn error_body_shapes_keep_the_status_component_and_hoist_single_inline_members() {
        let doc = crate::openapi::load(
            &std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("docs/openapi-surface/handwritten/error-body-shapes/openapi.yml"),
        )
        .unwrap();
        let config = crate::config::GenerateConfig::new(
            std::path::PathBuf::from("openapi.yml"),
            std::path::PathBuf::from("out"),
            Some("api".into()),
            None,
            None,
            crate::settings::ExtraFields::default(),
            "Nursery",
        )
        .unwrap();
        let ir = super::build(&doc, &config);
        assert!(ir.types.iter().any(|decl| matches!(
            decl,
            TypeDecl::Object(object) if object.name == "BadRequestErrorBody"
                && object.docstring.as_deref() == Some("The reservation is already occupied.")
        )));
        assert!(!ir.types.iter().any(|decl| matches!(
            decl,
            TypeDecl::DiscriminatedUnion(union) if union.name == "BadRequestErrorBody"
        )));
        assert!(ir.types.iter().any(|decl| matches!(
            decl,
            TypeDecl::Object(object) if object.name == "ConflictErrorBody"
                && object.fields.iter().any(|field| field.py_name == "state"
                    && field.type_ref == TypeRef::Named("ConflictErrorBodyState".into()))
        )));
        let response: crate::openapi::Response = serde_json::from_value(serde_json::json!({
            "description": "Conflict",
            "content": { "application/json": { "schema": { "oneOf": [{
                "type": "object", "properties": { "state": { "type": "string" } }
            }] } } }
        }))
        .unwrap();
        assert_eq!(
            super::error_body_type(&response, "ConflictError"),
            TypeRef::Named("ConflictErrorBody".into())
        );
        let response: crate::openapi::Response = serde_json::from_value(serde_json::json!({
            "description": "Conflict",
            "content": { "application/json": { "schema": { "oneOf": [{
                "$ref": "#/components/schemas/JournalContext"
            }] } } }
        }))
        .unwrap();
        assert_eq!(
            super::error_body_type(&response, "ConflictError"),
            TypeRef::Named("JournalContext".into())
        );
    }

    #[test]
    fn inline_single_reference_composition_examples_use_the_referenced_object_path() {
        let directory = tempfile::tempdir().unwrap();
        let spec = directory.path().join("openapi.json");
        let document = serde_json::json!({
            "openapi": "3.0.3", "info": {"title": "Harbor schedules", "version": "1"},
            "paths": {"/schedules": {"post": {
                "operationId": "create_schedule", "requestBody": {
                    "required": true, "content": {"application/json": {
                        "schema": {"allOf": [{"$ref": "#/components/schemas/Schedule"}],
                            "title": "Schedule input", "description": "A harbor departure."},
                        "example": {"label": "evening ferry"}
                    }}
                }, "responses": {"204": {"description": "Stored"}}
            }}},
            "components": {"schemas": {"Schedule": {
                "type": "object", "required": ["label"],
                "properties": {"label": {"type": "string"}},
                "example": {"label": "morning ferry"}
            }}}
        });
        std::fs::write(&spec, serde_json::to_vec(&document).unwrap()).unwrap();
        let doc = crate::openapi::load(&spec).unwrap();
        let media = &doc.paths["/schedules"]
            .post
            .as_ref()
            .unwrap()
            .request_body
            .as_ref()
            .unwrap()
            .content["application/json"];
        let schema = media.schema.as_ref().unwrap();
        assert_eq!(
            schema.reference.as_deref(),
            Some("#/components/schemas/Schedule")
        );
        assert!(schema.all_of.is_none());
        assert_eq!(schema.title.as_deref(), Some("Schedule input"));
        let config = crate::config::GenerateConfig::new(
            spec,
            directory.path().join("out"),
            Some("harbor".into()),
            None,
            None,
            crate::settings::ExtraFields::default(),
            "Harbor",
        )
        .unwrap();
        let ir = super::build(&doc, &config);
        let Some(RequestBody::Inline(fields)) = &ir.endpoints[0].request_body else {
            panic!("the normalized reference must flatten the component fields");
        };
        assert_eq!(fields.len(), 1);
        assert_eq!(fields[0].wire_name, "label");
        assert_eq!(fields[0].example.as_deref(), Some("\"evening ferry\""));
        assert!(!fields[0].schema_body_example);
    }

    #[test]
    fn referenced_union_schema_examples_reject_values_that_match_no_member() {
        for (lookback, accepted) in [
            (serde_json::json!(20), true),
            (serde_json::json!("twenty"), false),
        ] {
            let target: crate::openapi::Schema = serde_json::from_value(serde_json::json!({
                "oneOf": [{"type":"string","enum":["North"]},
                    {"type":"object","required":["Window"],"properties":{
                        "Window":{"type":"object","required":["lookback"],"properties":{
                            "lookback":{"type":"integer"}}}}}],
                "example":{"Window":{"lookback":lookback}}
            }))
            .unwrap();
            assert_eq!(
                super::referenced_example_literal(&target, &indexmap::IndexMap::new()).is_some(),
                accepted
            );
        }
    }

    #[test]
    fn media_object_example_supersedes_component_example_with_property_fallback() {
        for media in [false, true] {
            let mut document = serde_json::json!({
                "openapi": "3.0.3", "info": {"title": "Beacon permits", "version": "1"},
                "paths": {"/permits": {"post": {
                    "operationId": "issue_permit", "requestBody": {
                        "required": true, "content": {"application/json": {
                            "schema": {"$ref": "#/components/schemas/Permit"}
                        }}
                    }, "responses": {"204": {"description": "Stored"}}
                }}},
                "components": {"schemas": {"Permit": {
                    "type": "object", "required": ["label"], "properties": {
                        "label": {"type": "string"},
                        "scopes": {"type": "array", "items": {"type": "string"},
                            "example": ["property-scope"]},
                        "zone": {"type": "string"}
                    },
                    "example": {"label": "component-label", "scopes": ["component-scope"], "zone": "north"}
                }}}
            });
            if media {
                document["paths"]["/permits"]["post"]["requestBody"]["content"]
                    ["application/json"]["example"] =
                    serde_json::json!({"label": "media-label", "scopes": []});
            }
            let ir = build_document(document);
            let Some(RequestBody::Inline(fields)) = &ir.endpoints[0].request_body else {
                panic!("a referenced object is flattened")
            };
            let field = |name: &str| fields.iter().find(|field| field.wire_name == name).unwrap();
            assert_eq!(
                field("label").example.as_deref(),
                Some(if media {
                    "\"media-label\""
                } else {
                    "\"component-label\""
                })
            );
            assert_eq!(
                field("scopes").example.as_deref(),
                Some(if media {
                    "[\"property-scope\"]"
                } else {
                    "[\"component-scope\"]"
                })
            );
            assert_eq!(
                field("zone").example.as_deref(),
                if media { None } else { Some("\"north\"") }
            );
            assert_eq!(field("label").schema_body_example, !media);
        }
    }

