    #[test]
    fn nullable_request_schema_makes_the_body_optional() {
        let doc: OpenApi = serde_json::from_value(serde_json::json!({ "openapi": "3.1.0" }))
            .expect("3.1 document deserializes");
        let body: crate::openapi::RequestBody = serde_json::from_value(serde_json::json!({
            "content": { "application/json": { "schema": {
                "type": "object", "properties": {}, "nullable": true
            } } }
        }))
        .expect("request body deserializes");
        let mut hoister = InlineHoister {
            copying_refs: Vec::new(),
            root_types: &[],
            schemas: Some(&doc.components.schemas),
            out: Vec::new(),
        };
        let resolved =
            super::resolve_request_body(&doc, &[], &body, &mut hoister, "DeleteRequest", false);
        assert!(matches!(resolved, Some(RequestBody::Single(body)) if !body.required));
        let nullable_unknown: crate::openapi::RequestBody =
            serde_json::from_value(serde_json::json!({
                "content": { "application/json": { "schema": { "nullable": true } } }
            }))
            .expect("nullable unknown body deserializes");
        let resolved = super::resolve_request_body(
            &doc,
            &[],
            &nullable_unknown,
            &mut hoister,
            "DeleteRequest",
            false,
        );
        assert!(matches!(resolved, Some(RequestBody::Single(body)) if !body.required));

        let unknown: crate::openapi::RequestBody = serde_json::from_value(serde_json::json!({
            "content": { "application/json": { "schema": {} } }
        }))
        .expect("unknown request body deserializes");
        let resolved =
            super::resolve_request_body(&doc, &[], &unknown, &mut hoister, "DeleteRequest", false);
        assert!(
            matches!(resolved, Some(RequestBody::Single(ref body)) if body.required),
            "{resolved:?}"
        );
        // The document version does not enter into it. Only the schema's
        // `nullable` and the wrapper's own `required: false` relax it.
        let legacy_doc: OpenApi = serde_json::from_value(serde_json::json!({ "openapi": "3.0.1" }))
            .expect("3.0 document deserializes");
        let resolved = super::resolve_request_body(
            &legacy_doc,
            &[],
            &unknown,
            &mut hoister,
            "DeleteRequest",
            false,
        );
        assert!(
            matches!(resolved, Some(RequestBody::Single(ref body)) if body.required),
            "{resolved:?}"
        );
        let optional_unknown: crate::openapi::RequestBody =
            serde_json::from_value(serde_json::json!({
                "required": false,
                "content": { "application/json": { "schema": {} } }
            }))
            .expect("not-required unknown body deserializes");
        let resolved = super::resolve_request_body(
            &legacy_doc,
            &[],
            &optional_unknown,
            &mut hoister,
            "DeleteRequest",
            false,
        );
        assert!(matches!(resolved, Some(RequestBody::Single(body)) if !body.required));

        // An inline array's content-type header follows its schema's own title
        // or description, not its `$ref` items or the document version.
        let array = |schema: serde_json::Value| -> crate::openapi::RequestBody {
            serde_json::from_value(serde_json::json!({
                "required": true,
                "content": { "application/json": { "schema": schema } }
            }))
            .expect("array request body deserializes")
        };
        let block_items = serde_json::json!({ "$ref": "#/components/schemas/Block" });
        for (schema, header) in [
            (
                serde_json::json!({ "type": "array", "items": block_items }),
                false,
            ),
            (
                serde_json::json!({ "type": "array", "title": "Blocks", "items": block_items }),
                true,
            ),
            (
                serde_json::json!({ "type": "array", "description": "Blocks", "items": block_items }),
                true,
            ),
            (
                serde_json::json!({ "type": "array", "description": "", "items": block_items }),
                true,
            ),
        ] {
            let resolved = super::resolve_request_body(
                &doc,
                &[],
                &array(schema.clone()),
                &mut hoister,
                "BatchRequest",
                false,
            );
            assert!(
                matches!(resolved, Some(RequestBody::Single(ref body)) if body.content_type == header),
                "{schema}: {resolved:?}"
            );
        }
    }

    #[test]
